-- =============================================================================
-- Nishorgo 2.0 · Extended catalog: more categories, ~80 more plants, journal.
-- Reference data only (no users). Idempotent: skips rows that already exist.
-- Photos live in frontend/public/plants; credits in docs/IMAGE_CREDITS.md.
-- =============================================================================

insert into public.categories (slug, name, tagline, emoji, sort_order) values
  ('indoor-plants',     'Indoor Plants',       'Leafy greens that thrive in flats and offices', '🪴', 5),
  ('succulents-cacti',  'Succulents & Cacti',  'Sun-lovers that forgive a forgetful waterer',  '🌵', 6),
  ('climbers-hanging',  'Climbers & Hanging',  'Trail, twine and cover a bare wall',           '🍃', 7),
  ('bonsai',            'Bonsai',              'Living sculpture, shaped by hand',              '🌳', 8)
on conflict (slug) do nothing;

insert into public.products
  (name, scientific_name, category_id, short_description, description, price, compare_at_price, stock,
   low_stock_threshold, image_url, light, difficulty, water_every_days, fertilize_every_days,
   pet_friendly, air_purifying, edible, mature_height_cm, tags, is_featured)
select v.name, v.sci, c.id, v.short, v.descr, v.price, v.compare, v.stock, v.low, '/plants/' || v.img || '.webp',
       v.light::public.light_level, v.diff::public.care_difficulty, v.water, v.feed,
       v.pet, v.air, v.edible, v.height, v.tags, v.featured
  from (values
    -- ------------------------------------------------------------ Indoor Plants
    ('Monstera Deliciosa', 'Monstera deliciosa', 'indoor-plants',
     'The Swiss cheese plant — big, glossy, split leaves that make any room feel like a jungle.',
     E'A fast grower that rewards a bright spot with dramatic split leaves. Young plants arrive in a 10-inch pot with a moss pole so they can climb straight away.\n\n**Care tips**\n- Bright, indirect light; no harsh afternoon sun\n- Water when the top 5 cm of soil is dry\n- Wipe the leaves monthly so they can breathe\n\n**Good to know:** leaves only start to split once the plant is mature and getting enough light. Toxic to pets if chewed.',
     1250, 1450, 22, 5, 'monstera', 'bright_indirect', 'easy', 7, 30, false, true, false, 200,
     array['indoor', 'statement', 'tropical', 'large-leaf'], true),
    ('Snake Plant (Laurentii)', 'Dracaena trifasciata', 'indoor-plants',
     'Upright, sword-like leaves with golden edges. Nearly impossible to kill.',
     E'The ultimate beginner plant: it tolerates low light, missed waterings and dry air. It also releases oxygen at night, which makes it a classic bedroom plant.\n\n**Care tips**\n- Any light from dim corner to bright window\n- Water every 2–3 weeks; less in winter\n- Use a gritty, fast-draining mix\n\n**Good to know:** overwatering is the only real way to kill it. Mildly toxic to pets.',
     550, 650, 48, 8, 'snake-plant', 'low', 'easy', 14, 60, false, true, false, 90,
     array['indoor', 'low-light', 'beginner', 'bedroom', 'drought-tolerant'], true),
    ('ZZ Plant', 'Zamioculcas zamiifolia', 'indoor-plants',
     'Waxy, deep-green leaves that shrug off low light and neglect.',
     E'Stores water in its potato-like rhizomes, so it is happy to be forgotten for weeks. Perfect for offices and corridors with no windows.\n\n**Care tips**\n- Low to bright indirect light\n- Water only when the soil is completely dry\n- Feed lightly in summer\n\n**Good to know:** all parts are toxic if eaten — keep away from curious pets and children.',
     750, null, 30, 6, 'zz-plant', 'low', 'easy', 14, 60, false, true, false, 70,
     array['indoor', 'low-light', 'office', 'beginner'], false),
    ('Peace Lily', 'Spathiphyllum wallisii', 'indoor-plants',
     'Elegant white blooms and glossy leaves; it droops to tell you it is thirsty.',
     E'One of the few flowering plants that blooms happily in low light. A dramatic droop means it needs water — it perks up within an hour.\n\n**Care tips**\n- Medium to low indirect light\n- Keep the soil lightly moist\n- Mist in dry winter months\n\n**Good to know:** toxic to cats and dogs.',
     480, 560, 36, 6, 'peace-lily', 'low', 'easy', 4, 30, false, true, false, 60,
     array['indoor', 'flowers', 'white', 'low-light', 'gift'], false),
    ('Fiddle Leaf Fig', 'Ficus lyrata', 'indoor-plants',
     'Large violin-shaped leaves on a tall stem — the designer''s favourite.',
     E'A statement plant for a bright living room. It dislikes being moved, so choose its spot carefully and let it settle.\n\n**Care tips**\n- Bright light, ideally near an east-facing window\n- Water when the top 5 cm is dry; never let it sit in water\n- Rotate a quarter turn every month for even growth\n\n**Good to know:** dropping leaves usually means a draught or a sudden move.',
     1650, 1900, 9, 3, 'fiddle-leaf-fig', 'bright_indirect', 'expert', 7, 30, false, true, false, 180,
     array['indoor', 'statement', 'large-leaf', 'designer'], false),
    ('Rubber Plant (Burgundy)', 'Ficus elastica', 'indoor-plants',
     'Thick, glossy, almost-black leaves on a sturdy upright stem.',
     E'Tougher than a fiddle leaf fig and just as striking. New leaves unfurl from a bright red sheath.\n\n**Care tips**\n- Bright, indirect light keeps the colour deep\n- Water when the top half of the soil is dry\n- Dust the leaves with a damp cloth\n\n**Good to know:** the milky sap can irritate skin and is toxic to pets.',
     890, null, 18, 4, 'rubber-plant', 'bright_indirect', 'easy', 7, 30, false, true, false, 150,
     array['indoor', 'statement', 'dark-foliage'], false),
    ('Areca Palm', 'Dypsis lutescens', 'indoor-plants',
     'Feathery, arching fronds that bring a soft tropical feel indoors.',
     E'A lush, multi-stemmed palm that is safe around pets and a natural humidifier for dry, air-conditioned rooms.\n\n**Care tips**\n- Bright, filtered light\n- Keep the soil evenly moist but never soggy\n- Use filtered or rested tap water to avoid brown tips',
     950, null, 15, 4, 'areca-palm', 'bright_indirect', 'moderate', 4, 30, true, true, false, 180,
     array['indoor', 'palm', 'pet-safe', 'tropical'], false),
    ('Aglaonema ''Red Siam''', 'Aglaonema commutatum', 'indoor-plants',
     'Pink-and-green patterned leaves that brighten a dim corner.',
     E'Chinese evergreens are some of the most forgiving foliage plants. This variety keeps its pink blush even in moderate light.\n\n**Care tips**\n- Low to medium indirect light\n- Water when the top 3 cm is dry\n- Keep away from cold air-conditioner blasts\n\n**Good to know:** toxic to pets if chewed.',
     650, 720, 26, 5, 'aglaonema', 'low', 'easy', 7, 30, false, true, false, 50,
     array['indoor', 'colourful', 'low-light', 'pink'], false),
    ('Prayer Plant', 'Maranta leuconeura', 'indoor-plants',
     'Painted leaves that fold up at night like hands in prayer.',
     E'Watch it move: the leaves lie flat by day and lift at dusk. A pet-safe pick for a bathroom or kitchen shelf.\n\n**Care tips**\n- Medium, indirect light; direct sun fades the pattern\n- Keep the soil lightly moist\n- Loves humidity — group it with other plants',
     480, null, 20, 5, 'prayer-plant', 'medium', 'moderate', 3, 30, true, false, false, 30,
     array['indoor', 'pet-safe', 'patterned', 'compact'], false),
    ('Parlor Palm', 'Chamaedorea elegans', 'indoor-plants',
     'A graceful little palm that copes with low light and is safe for pets.',
     E'Victorian households grew it in their darkest parlours, hence the name. It grows slowly and stays a manageable size for years.\n\n**Care tips**\n- Low to medium light\n- Water when the top few centimetres are dry\n- Trim brown fronds at the base',
     550, null, 28, 6, 'parlor-palm', 'low', 'easy', 7, 30, true, true, false, 120,
     array['indoor', 'palm', 'pet-safe', 'low-light'], false),
    ('Spider Plant', 'Chlorophytum comosum', 'indoor-plants',
     'Striped, arching leaves and dangling baby plants you can pot up for friends.',
     E'Cheerful, fast and pet-safe. Mature plants send out runners with little plantlets — root them in water and you have free gifts.\n\n**Care tips**\n- Medium to bright indirect light\n- Water when the top of the soil is dry\n- Brown tips usually mean fluoride in tap water',
     260, 320, 55, 10, 'spider-plant', 'medium', 'easy', 5, 30, true, true, false, 40,
     array['indoor', 'pet-safe', 'beginner', 'hanging', 'propagation'], false),
    ('Dieffenbachia ''Camille''', 'Dieffenbachia seguine', 'indoor-plants',
     'Cream-centred leaves edged in green — bold and easy.',
     E'A quick grower that fills a corner fast. Turn it regularly; it leans towards the light.\n\n**Care tips**\n- Medium, indirect light\n- Water when the top 3 cm are dry\n- Feed monthly in the growing season\n\n**Good to know:** the sap is toxic and can numb the mouth — keep away from pets and children.',
     520, null, 0, 4, 'dieffenbachia', 'medium', 'easy', 5, 30, false, true, false, 90,
     array['indoor', 'variegated', 'fast-growing'], false),
    ('Money Tree', 'Pachira aquatica', 'indoor-plants',
     'A braided trunk topped with glossy hand-shaped leaves; said to bring good fortune.',
     E'A popular housewarming and office-opening gift. The braided trunk is formed by growers over several years.\n\n**Care tips**\n- Bright, indirect light\n- Water thoroughly, then let the top half dry\n- Rotate weekly for even growth',
     1100, 1300, 14, 4, 'money-tree', 'bright_indirect', 'moderate', 7, 30, true, true, false, 150,
     array['indoor', 'gift', 'pet-safe', 'braided'], false),
    ('Lucky Bamboo (3-tier)', 'Dracaena sanderiana', 'indoor-plants',
     'A tiered arrangement of lucky bamboo in a glass vase with pebbles.',
     E'Grows happily in water. Each tier is a symbol of happiness, wealth and long life, so it is a favourite gift for Eid and new homes.\n\n**Care tips**\n- Low to medium indirect light\n- Top up with clean water weekly; replace fully every month\n- One drop of liquid fertiliser every two months\n\n**Good to know:** toxic to pets.',
     350, null, 40, 8, 'lucky-bamboo', 'low', 'easy', 7, 60, false, false, false, 60,
     array['indoor', 'gift', 'water-grown', 'feng-shui'], false),

    -- ------------------------------------------------------- Succulents & Cacti
    ('Aloe Vera', 'Aloe vera', 'succulents-cacti',
     'The first-aid plant: soothing gel in every thick, spiky leaf.',
     E'Snap a leaf to use the cooling gel on minor burns and sunburn. It produces pups at the base that you can repot.\n\n**Care tips**\n- Full sun or the brightest window you have\n- Water deeply every 2–3 weeks\n- Use a cactus mix in a terracotta pot\n\n**Good to know:** the gel is for skin; the plant is toxic to pets if eaten.',
     220, 260, 60, 10, 'aloe-vera', 'full_sun', 'easy', 14, 60, false, true, false, 45,
     array['succulent', 'medicinal', 'beginner', 'drought-tolerant'], false),
    ('Jade Plant', 'Crassula ovata', 'succulents-cacti',
     'Plump, coin-shaped leaves on a woody trunk; a symbol of prosperity.',
     E'Jade plants live for decades and slowly become miniature trees. In full sun the leaf edges blush red.\n\n**Care tips**\n- Full sun to bright light\n- Water when the soil is completely dry\n- Prune to shape after the monsoon\n\n**Good to know:** toxic to cats and dogs.',
     380, null, 33, 6, 'jade-plant', 'full_sun', 'easy', 14, 60, false, false, false, 60,
     array['succulent', 'gift', 'prosperity', 'drought-tolerant'], false),
    ('Echeveria ''Mexican Snowball''', 'Echeveria elegans', 'succulents-cacti',
     'A perfect pale-blue rosette that fits on any windowsill.',
     E'Compact and photogenic. Grows best in a sunny spot with a little afternoon shade during peak summer.\n\n**Care tips**\n- Bright sun\n- Water from the bottom when the soil is dry\n- Keep water out of the rosette to prevent rot',
     180, null, 70, 10, 'echeveria', 'full_sun', 'easy', 10, 60, true, false, false, 10,
     array['succulent', 'compact', 'pet-safe', 'desk'], false),
    ('Zebra Haworthia', 'Haworthiopsis attenuata', 'succulents-cacti',
     'White-striped spiky leaves; a tidy succulent for a desk or bookshelf.',
     E'Unlike most succulents it tolerates less light, which makes it ideal for indoor shelves. Pet-safe.\n\n**Care tips**\n- Bright, indirect light\n- Water every 2–3 weeks\n- Repot every two years in fresh cactus mix',
     200, null, 52, 10, 'haworthia', 'bright_indirect', 'easy', 14, 60, true, false, false, 12,
     array['succulent', 'compact', 'pet-safe', 'desk', 'beginner'], false),
    ('Golden Barrel Cactus', 'Echinocactus grusonii', 'succulents-cacti',
     'A round, golden-spined cactus that glows in the sun.',
     E'A slow, sculptural cactus for the sunniest balcony. Handle with the folded newspaper trick when repotting.\n\n**Care tips**\n- Full sun\n- Water every 3 weeks in summer, monthly in winter\n- Protect from monsoon downpours',
     450, null, 21, 4, 'golden-barrel', 'full_sun', 'easy', 21, 90, false, false, false, 30,
     array['cactus', 'sculptural', 'drought-tolerant', 'balcony'], false),
    ('Christmas Cactus', 'Schlumbergera truncata', 'succulents-cacti',
     'Cascading stems that burst into pink blooms in the cool months.',
     E'A forest cactus, not a desert one, so it likes more water and less sun than you might expect. Pet-safe.\n\n**Care tips**\n- Bright, indirect light\n- Keep slightly moist while flowering\n- Long nights in autumn trigger the buds',
     420, null, 17, 4, 'christmas-cactus', 'bright_indirect', 'moderate', 7, 30, true, false, false, 30,
     array['cactus', 'flowers', 'pink', 'pet-safe', 'hanging'], false),
    ('Crown of Thorns', 'Euphorbia milii', 'succulents-cacti',
     'Thorny stems with bright red bracts almost all year round.',
     E'Thrives in the heat and flowers non-stop on a sunny rooftop. One of the most reliable bloomers in Bangladesh.\n\n**Care tips**\n- Full sun\n- Water when the top half of the soil is dry\n- Wear gloves when pruning\n\n**Good to know:** the milky sap is an irritant and toxic to pets.',
     350, null, 29, 6, 'crown-of-thorns', 'full_sun', 'easy', 7, 30, false, false, false, 60,
     array['succulent', 'flowers', 'red', 'rooftop', 'heat-tolerant'], false),
    ('Adenium (Desert Rose)', 'Adenium obesum', 'succulents-cacti',
     'A swollen bonsai-like trunk crowned with trumpet flowers.',
     E'The rooftop collector''s favourite. Grafted plants bloom in pink, red and white, and the caudex grows fatter every year.\n\n**Care tips**\n- Full sun — at least 6 hours\n- Water well in summer, sparingly in winter\n- Feed with a high-phosphorus fertiliser for more flowers\n\n**Good to know:** the sap is highly toxic; keep away from pets and children.',
     650, 790, 24, 5, 'adenium', 'full_sun', 'moderate', 5, 30, false, false, false, 60,
     array['succulent', 'flowers', 'pink', 'rooftop', 'collector'], true),
    ('Kalanchoe', 'Kalanchoe blossfeldiana', 'succulents-cacti',
     'Clusters of tiny bright blooms that last for weeks.',
     E'A long-lasting flowering succulent that makes a cheerful gift. Blooms come in red, orange, yellow and pink.\n\n**Care tips**\n- Bright light\n- Water when the soil is dry\n- Pinch off spent flower heads\n\n**Good to know:** toxic to cats and dogs.',
     250, null, 38, 8, 'kalanchoe', 'full_sun', 'easy', 7, 30, false, false, false, 30,
     array['succulent', 'flowers', 'gift', 'colourful'], false),
    ('Bunny Ear Cactus', 'Opuntia microdasys', 'succulents-cacti',
     'Paddle-shaped pads dotted with soft-looking (but prickly!) glochids.',
     E'A playful cactus that grows quickly in the sun. Those fluffy dots are tiny barbs — admire, don''t pat.\n\n**Care tips**\n- Full sun\n- Water every 3 weeks\n- Repot with tongs or a folded towel',
     320, null, 0, 4, 'bunny-ear-cactus', 'full_sun', 'easy', 21, 90, false, false, false, 40,
     array['cactus', 'quirky', 'drought-tolerant'], false),

    -- ------------------------------------------------------- Climbers & Hanging
    ('Golden Pothos (Money Plant)', 'Epipremnum aureum', 'climbers-hanging',
     'The classic money plant: heart-shaped, golden-splashed leaves that trail or climb.',
     E'Grows in soil or a bottle of water, in low light or bright, and forgives almost anything. Let it trail from a shelf or train it up a pole.\n\n**Care tips**\n- Low to bright indirect light\n- Water when the top 3 cm are dry\n- Snip and root cuttings in water to fill the pot\n\n**Good to know:** toxic to pets if chewed.',
     320, 380, 65, 10, 'pothos', 'low', 'easy', 7, 30, false, true, false, 300,
     array['hanging', 'trailing', 'beginner', 'low-light', 'money-plant'], true),
    ('Heartleaf Philodendron', 'Philodendron hederaceum', 'climbers-hanging',
     'Soft, heart-shaped leaves on long trailing vines.',
     E'A fast, forgiving trailer for a bookshelf or hanging basket. Pinch the tips to keep it bushy.\n\n**Care tips**\n- Medium, indirect light\n- Water when the top of the soil is dry\n- Feed monthly in summer\n\n**Good to know:** toxic to pets.',
     380, null, 34, 6, 'philodendron', 'medium', 'easy', 7, 30, false, true, false, 250,
     array['hanging', 'trailing', 'indoor', 'heart-shaped'], false),
    ('String of Pearls', 'Curio rowleyanus', 'climbers-hanging',
     'Strands of round, bead-like leaves that cascade over the pot.',
     E'A show-stopping hanging succulent. Shallow pots and a gritty mix keep the shallow roots healthy.\n\n**Care tips**\n- Bright, indirect light\n- Water when the pearls look slightly wrinkled\n- Avoid crushing the strands on the pot rim\n\n**Good to know:** toxic to pets.',
     450, 520, 12, 4, 'string-of-pearls', 'bright_indirect', 'moderate', 10, 60, false, false, false, 60,
     array['hanging', 'succulent', 'trailing', 'unusual'], false),
    ('Boston Fern', 'Nephrolepis exaltata', 'climbers-hanging',
     'Lush, arching fronds that love humid verandas.',
     E'A classic for shaded verandas and bathrooms. It loves the monsoon humidity and is safe for pets.\n\n**Care tips**\n- Medium, indirect light\n- Keep the soil consistently moist\n- Mist daily in dry weather',
     420, null, 27, 6, 'boston-fern', 'medium', 'moderate', 2, 30, true, true, false, 60,
     array['hanging', 'fern', 'pet-safe', 'humidity'], false),
    ('Bougainvillea (Magenta)', 'Bougainvillea glabra', 'climbers-hanging',
     'Sheets of papery magenta bracts that cover walls and rooftop railings.',
     E'Thrives on heat and a little neglect — a classic for Dhaka rooftops and boundary walls. More sun and less water means more colour.\n\n**Care tips**\n- Full sun, 6+ hours\n- Let the soil dry between waterings\n- Prune after each flush to keep it compact\n\n**Good to know:** sharp thorns — wear gloves when training it.',
     380, 450, 31, 6, 'bougainvillea', 'full_sun', 'easy', 4, 30, false, false, false, 300,
     array['climber', 'flowers', 'pink', 'rooftop', 'heat-tolerant'], true),
    ('Beli (Arabian Jasmine)', 'Jasminum sambac', 'climbers-hanging',
     'Small white flowers with an intoxicating evening fragrance.',
     E'Beli flowers open at dusk and scent the whole balcony. Pick them for garlands, hair or a bowl of water on the table.\n\n**Care tips**\n- Full sun\n- Water regularly in summer\n- Prune after flowering to encourage new shoots',
     290, null, 44, 8, 'jasmine', 'full_sun', 'easy', 2, 21, true, false, false, 150,
     array['climber', 'flowers', 'white', 'fragrant', 'pet-safe'], false),
    ('Madhabilata (Rangoon Creeper)', 'Combretum indicum', 'climbers-hanging',
     'Clusters of flowers that open white and turn pink, then red.',
     E'A vigorous climber for a pergola or boundary wall, with a sweet fragrance at night. Each cluster shows three colours at once.\n\n**Care tips**\n- Full sun\n- Give it a sturdy support\n- Cut back hard in late winter',
     340, null, 19, 4, 'madhabilata', 'full_sun', 'easy', 3, 30, false, false, false, 400,
     array['climber', 'flowers', 'fragrant', 'pergola'], false),
    ('Passion Fruit Vine', 'Passiflora edulis', 'climbers-hanging',
     'Exotic flowers followed by tangy purple fruit on a fast-growing vine.',
     E'Train it over a rooftop trellis and expect fruit within 12–18 months. The flowers alone are worth growing it for.\n\n**Care tips**\n- Full sun\n- Water deeply twice a week in summer\n- Feed monthly with a balanced fertiliser',
     420, null, 16, 4, 'passion-fruit', 'full_sun', 'moderate', 2, 30, false, false, true, 500,
     array['climber', 'edible', 'fruit', 'rooftop'], false),
    ('English Ivy', 'Hedera helix', 'climbers-hanging',
     'Classic lobed leaves that trail from a basket or climb a wall.',
     E'A tough trailer that prefers cooler, shaded spots. Great for softening a shaded balcony wall.\n\n**Care tips**\n- Medium, indirect light\n- Keep the soil lightly moist\n- Rinse the leaves to deter spider mites\n\n**Good to know:** toxic to pets.',
     300, null, 23, 5, 'english-ivy', 'medium', 'easy', 5, 30, false, true, false, 200,
     array['hanging', 'trailing', 'shade'], false),

    -- ------------------------------------------------------------------- Bonsai
    ('Ficus Ginseng Bonsai', 'Ficus microcarpa', 'bonsai',
     'A sturdy, thick-rooted ficus — the easiest bonsai to start with.',
     E'Arrives in a ceramic bonsai tray with a care card. Ficus tolerates indoor conditions better than most bonsai.\n\n**Care tips**\n- Bright light, a little morning sun\n- Water when the top of the soil is dry; never let it dry out fully\n- Trim new shoots back to two leaves',
     1800, 2100, 11, 3, 'ficus-bonsai', 'bright_indirect', 'moderate', 3, 30, false, true, false, 35,
     array['bonsai', 'gift', 'indoor', 'beginner-bonsai'], true),
    ('Chinese Elm Bonsai', 'Ulmus parvifolia', 'bonsai',
     'Fine, tiny leaves and a gnarled trunk; a classic outdoor bonsai.',
     E'A forgiving outdoor bonsai with beautiful bark. It responds well to pruning and wiring.\n\n**Care tips**\n- Full sun outdoors\n- Water as soon as the topsoil feels dry — daily in summer\n- Repot every two years in spring',
     2400, null, 6, 2, 'chinese-elm', 'full_sun', 'expert', 2, 21, true, false, false, 40,
     array['bonsai', 'outdoor', 'collector'], false),
    ('Dwarf Jade Bonsai', 'Portulacaria afra', 'bonsai',
     'Small round leaves on red stems; drought-tolerant and pet-safe.',
     E'Often confused with the jade plant, this South African succulent makes a superb low-maintenance bonsai.\n\n**Care tips**\n- Full sun\n- Water when the soil is dry\n- Prune any time to refine the shape',
     1500, null, 9, 3, 'portulacaria', 'full_sun', 'moderate', 7, 30, true, false, false, 30,
     array['bonsai', 'succulent', 'pet-safe', 'beginner-bonsai'], false),
    ('Fukien Tea Bonsai', 'Ehretia microphylla', 'bonsai',
     'Dark glossy leaves with tiny white flowers and red berries.',
     E'A beautiful indoor-outdoor bonsai that flowers on and off all year. It dislikes drying out, so check it daily.\n\n**Care tips**\n- Bright light\n- Keep the soil evenly moist\n- Mist regularly in dry weather',
     2200, 2500, 5, 2, 'fukien-tea', 'bright_indirect', 'expert', 2, 21, false, false, false, 30,
     array['bonsai', 'flowers', 'collector'], false),
    ('Juniper Bonsai', 'Juniperus procumbens', 'bonsai',
     'Needle-like foliage and a windswept trunk — the iconic bonsai look.',
     E'An outdoor tree that needs sun and fresh air; it will not survive indoors. Pinch the foliage pads to keep them dense.\n\n**Care tips**\n- Full sun, outdoors all year\n- Water when the topsoil starts to dry\n- Feed monthly in the growing season',
     2600, null, 4, 2, 'juniper-bonsai', 'full_sun', 'expert', 3, 30, false, false, false, 30,
     array['bonsai', 'outdoor', 'collector', 'conifer'], false),
    ('Banyan Bonsai', 'Ficus benghalensis', 'bonsai',
     'Bangladesh''s great shade tree in miniature, with dangling aerial roots.',
     E'Grown for six years by our partner nursery in Jessore. Aerial roots drop from the branches and slowly thicken into new trunks.\n\n**Care tips**\n- Full sun to bright light\n- Water generously in summer\n- Trim long shoots after the monsoon',
     3200, 3600, 3, 2, 'banyan', 'full_sun', 'moderate', 3, 30, false, true, false, 45,
     array['bonsai', 'native', 'collector', 'aerial-roots'], false),

    -- ---------------------------------------------------------- Flowering Plants
    ('Joba (Hibiscus)', 'Hibiscus rosa-sinensis', 'flowering',
     'Big red trumpet flowers almost every day of the year.',
     E'The joba is a fixture of Bangladeshi courtyards. Each flower lasts a day, but a healthy plant opens new ones constantly.\n\n**Care tips**\n- Full sun\n- Water when the topsoil is dry\n- Feed every two weeks while flowering\n- Spray neem oil if you see mealybugs',
     260, 300, 42, 8, 'hibiscus', 'full_sun', 'easy', 2, 14, true, false, false, 150,
     array['flowers', 'red', 'heat-tolerant', 'daily-blooms'], false),
    ('Shapla (Water Lily)', 'Nymphaea nouchali', 'flowering',
     'Bangladesh''s national flower, ready to float in a tub or bowl.',
     E'Grown in a pot of clay soil that sits in a water-filled tub. Flowers open in the morning and close in the afternoon.\n\n**Care tips**\n- Full sun, at least 6 hours\n- Keep the pot submerged 15–30 cm\n- Push a fertiliser tablet into the clay monthly',
     650, null, 8, 3, 'shapla', 'full_sun', 'moderate', 1, 30, false, false, false, 20,
     array['flowers', 'aquatic', 'national-flower', 'pink'], false),
    ('Rajanigandha (Tuberose)', 'Agave amica', 'flowering',
     'Tall spikes of waxy white flowers with a heavenly evening scent.',
     E'Sold as a clump of healthy bulbs already sprouting. A few stems will perfume a whole room — a wedding and festival favourite.\n\n**Care tips**\n- Full sun\n- Water regularly while the spikes form\n- Cut stems when the lowest buds open',
     220, null, 37, 8, 'tuberose', 'full_sun', 'easy', 3, 21, false, false, false, 80,
     array['flowers', 'white', 'fragrant', 'bulb', 'festival'], false),
    ('Kamini (Orange Jasmine)', 'Murraya paniculata', 'flowering',
     'A glossy shrub covered in tiny white flowers with a citrus scent.',
     E'Blooms in flushes after rain, filling the evening air with fragrance. Makes a neat hedge or a pot specimen.\n\n**Care tips**\n- Full sun to part shade\n- Water when the topsoil dries\n- Prune lightly after flowering',
     350, null, 25, 5, 'kamini', 'full_sun', 'easy', 3, 30, false, false, false, 200,
     array['flowers', 'white', 'fragrant', 'hedge'], false),
    ('Gandharaj (Gardenia)', 'Gardenia jasminoides', 'flowering',
     'Creamy white blossoms with one of the richest scents in the garden.',
     E'Gandharaj prefers slightly acidic soil and steady moisture. Yellowing leaves usually mean it needs an acid feed.\n\n**Care tips**\n- Bright light with afternoon shade\n- Keep the soil evenly moist\n- Feed with an acid-loving plant fertiliser',
     420, 480, 18, 4, 'gardenia', 'bright_indirect', 'moderate', 2, 21, false, false, false, 120,
     array['flowers', 'white', 'fragrant'], false),
    ('Nayantara (Periwinkle)', 'Catharanthus roseus', 'flowering',
     'Cheerful pink and white flowers that bloom through the hottest months.',
     E'Practically unstoppable in heat and sun. Perfect for window boxes and the edges of rooftop planters.\n\n**Care tips**\n- Full sun\n- Water when the soil is dry\n- Avoid overhead watering in the monsoon\n\n**Good to know:** toxic if eaten.',
     120, null, 80, 12, 'periwinkle', 'full_sun', 'easy', 2, 21, false, false, false, 40,
     array['flowers', 'pink', 'heat-tolerant', 'beginner', 'window-box'], false),
    ('Rangan (Ixora)', 'Ixora coccinea', 'flowering',
     'Dense clusters of scarlet flowers on a compact shrub.',
     E'Loved by butterflies and children who sip the nectar. Blooms most of the year in warm weather.\n\n**Care tips**\n- Full sun\n- Keep the soil slightly moist\n- Feed monthly; add iron if leaves yellow',
     300, null, 32, 6, 'ixora', 'full_sun', 'easy', 3, 21, false, false, false, 120,
     array['flowers', 'red', 'butterflies', 'shrub'], false),
    ('Zinnia (Mixed Colours)', 'Zinnia elegans', 'flowering',
     'Bright pom-pom flowers in every colour — great for cutting.',
     E'Fast, sun-loving and pet-safe. The more you cut, the more it flowers.\n\n**Care tips**\n- Full sun\n- Water at the base to avoid powdery mildew\n- Deadhead regularly',
     140, null, 58, 10, 'zinnia', 'full_sun', 'easy', 2, 21, true, false, false, 60,
     array['flowers', 'colourful', 'pet-safe', 'cut-flowers', 'beginner'], false),
    ('Chandramallika (Chrysanthemum)', 'Chrysanthemum indicum', 'flowering',
     'Winter''s showpiece: big, layered blooms in gold, white and bronze.',
     E'Buy it in autumn for a spectacular display through December and January. Pinch the tips early for a bushier plant.\n\n**Care tips**\n- Full sun\n- Keep evenly moist while in bud\n- Feed every two weeks until buds show colour\n\n**Good to know:** toxic to cats and dogs.',
     260, null, 0, 6, 'chrysanthemum', 'full_sun', 'moderate', 2, 14, false, false, false, 50,
     array['flowers', 'yellow', 'winter', 'festival'], false),
    ('Petunia (Wave Mix)', 'Petunia × atkinsiana', 'flowering',
     'Trailing petunias that spill colour over baskets and railings.',
     E'A winter classic for hanging baskets. Pinch back leggy stems in mid-season for a second flush.\n\n**Care tips**\n- Full sun\n- Water when the topsoil dries\n- Feed weekly with a dilute fertiliser',
     150, null, 46, 10, 'petunia', 'full_sun', 'easy', 2, 14, true, false, false, 30,
     array['flowers', 'purple', 'hanging', 'winter', 'pet-safe'], false),
    ('Gerbera Daisy', 'Gerbera jamesonii', 'flowering',
     'Large, perfect daisies in vivid red, orange and yellow.',
     E'A favourite cut flower that also performs beautifully in pots. Plant the crown slightly above the soil to avoid rot.\n\n**Care tips**\n- Full sun to bright light\n- Water at the base, never on the crown\n- Feed every two weeks while flowering',
     280, 320, 30, 6, 'gerbera', 'full_sun', 'moderate', 3, 14, true, false, false, 40,
     array['flowers', 'colourful', 'pet-safe', 'cut-flowers', 'gift'], false),
    ('Anthurium (Red)', 'Anthurium andraeanum', 'flowering',
     'Glossy heart-shaped red blooms that last for months indoors.',
     E'One of the longest-lasting flowering houseplants. Each bloom can last eight weeks.\n\n**Care tips**\n- Bright, indirect light\n- Water when the top 3 cm are dry\n- Use an airy orchid-style mix\n\n**Good to know:** toxic to pets.',
